use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    ensures
        // After the call, the vector's contents are the reverse
        // of what they were at entry.
        a@ == old(a@).rev(),
{
    // n is the length of the vector
    let n: nat = a.len();
    // orig holds the original contents as a Seq<i32>
    let orig: Seq<i32> = a@;

    // Trivial cases: empty or singleton vector are already reversed
    if n < 2 {
        return;
    }

    let mut i: nat = 0;
    let mut j: nat = n - 1;

    // We will swap a[i] and a[j], then move inward.
    // Invariant tracks that:
    //  1. For k < i, a[k] == orig[n - 1 - k]        (prefix has been reversed)
    //  2. For i <= k <= j, a[k] == orig[k]          (middle untouched)
    //  3. For j < k < n, a[k] == orig[n - 1 - k]    (suffix has been reversed)
    while i < j
        invariant
            // bounds on i,j
            j < n,
            i <= j + 1,
            // prefix [0..i) is already reversed
            forall |k: nat| k < i ==> a@[k] == orig[n - 1 - k],
            // middle [i..=j] is still original
            forall |k: nat| i <= k && k <= j ==> a@[k] == orig[k],
            // suffix (j..n) is reversed
            forall |k: nat| j < k && k < n ==> a@[k] == orig[n - 1 - k],
        decreases j - i,
    {
        // swap a[i] and a[j]
        let tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;

        // move inward
        i = i + 1;
        j = j - 1;
    }

    // At loop exit i >= j, and from the invariants one
    // can show that for every k < n: a[k] == orig[n - 1 - k].
    // Hence the entire vector is reversed.
    assert(a@ == orig.rev());
}

} // end verus!

